module protocol::ctoken_table;

use std::type_name::{Self, TypeName};
use sui::bag::{Self, Bag};
use sui::balance::{Self, Balance};

use sui::table::{Self, Table};

use protocol::ctoken::CToken;
use protocol::error;
use protocol::generic_store::{Self, GenericCoinTypeStorage};

/// Tracks the ctoken stored and the underlying coin types
public struct CTokenTable has key, store {
    id: UID,
    // a mapping from the underlying coin type to ctoken types
    coin_types: GenericCoinTypeStorage<TypeName>,
    // use table instead of vec set as one needs to query balance by TypeName while balances is a bag and borrow operations need explicit types
    ctoken_values: Table<TypeName, u64>,
    balances: Bag,
}

public(package) fun new(ctx: &mut TxContext): CTokenTable {
    CTokenTable {
        id: object::new(ctx),
        coin_types: generic_store::new(ctx),
        ctoken_values: table::new(ctx),
        balances: bag::new(ctx),
    }
}

public(package) fun ctoken_value_by_coin_type(self: &CTokenTable, name: TypeName): u64 {
    if (!self.coin_types.supports_type<TypeName>(name)) { 0 } 
    else {
        let ctoken_type = self.coin_types.load_by_type(name);
        self.ctoken_value_by_ctoken_type(*ctoken_type)
    }
}

public(package) fun ctoken_value_by_ctoken_type(self: &CTokenTable, name: TypeName): u64 {
    if (!self.ctoken_values.contains(name)) { return 0 };
    *self.ctoken_values.borrow(name)
}

public(package) fun is_supporting_collateral<MarketType, CoinType>(self: &CTokenTable): bool {
    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    self.ctoken_values.contains(ctoken_type)
}

public(package) fun supported_coin_types(self: &CTokenTable): vector<TypeName> {
    if (self.coin_types.is_empty()) { vector::empty() } 
    else { self.coin_types.keys() }
}

public(package) fun support_collateral_token<MarketType, CoinType>(self: &mut CTokenTable) {
    let ctoken_type = ctoken_type_name<MarketType, CoinType>();

    // we are using ctoken type as the checking key and only coin_types to track actual collateral
    assert!(!self.ctoken_values.contains(ctoken_type), error::constraint_double_support_ctoken());

    self.coin_types.store<TypeName, CoinType>(ctoken_type);

    self.balances.add(ctoken_type, balance::zero<CToken<MarketType, CoinType>>());
    self.ctoken_values.add(ctoken_type, 0);
}

public(package) fun join_ctoken<MarketType, CoinType>(self: &mut CTokenTable, balance: Balance<CToken<MarketType, CoinType>>) {
    assert!(balance.value() > 0, error::reserve_join_zero_value());
    assert!(self.coin_types.supports<TypeName, CoinType>());

    let ctoken_type = ctoken_type_name<MarketType, CoinType>();

    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    let total = in_bag_balance.join(balance);

    let val = self.ctoken_values.borrow_mut(ctoken_type);
    *val = total;
}

/// Reverts if amount is more than balance, caller should ensure the condition is met.
public(package) fun split_ctoken<MarketType, CoinType>(self: &mut CTokenTable, amount: u64): Balance<CToken<MarketType, CoinType>> {
    assert!(amount > 0, error::reserve_split_zero_value());

    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);

    assert!(in_bag_balance.value() >= amount, error::constraint_split_ctoken_too_many());

    let b = in_bag_balance.split(amount);
    if (in_bag_balance.value() == 0) {
        self.coin_types.remove<TypeName, CoinType>();

        let empty_balance = bag::remove<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
        empty_balance.destroy_zero();

        self.ctoken_values.remove(ctoken_type);
    } else {
        let val = self.ctoken_values.borrow_mut(ctoken_type);
        *val = in_bag_balance.value();
    };

    b
}

public(package) fun ctoken_type_name<MarketType, CoinType>(): TypeName {
    type_name::with_defining_ids<CToken<MarketType, CoinType>>()
}


/// Mark this as test only for now, ctoken table is used in obligation, once an obligation is created, it will not be removed
#[test_only]
fun destroy_empty(self: CTokenTable) {
    let CTokenTable { id, balances, coin_types, ctoken_values } = self;

    assert!(coin_types.is_empty());
    assert!(ctoken_values.is_empty());

    object::delete(id);
    bag::destroy_empty(balances);
    std::unit_test::destroy(coin_types);
    table::destroy_empty(ctoken_values);
}

#[test_only]
fun remove_collateral<MarketType, CoinType>(self: &mut CTokenTable) {
    let ctoken_type = type_name::with_defining_ids<CToken<MarketType, CoinType>>();

    let _ = self.coin_types.remove<TypeName, CoinType>();

    let empty_balance = bag::remove<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    empty_balance.destroy_zero();

    self.ctoken_values.remove(ctoken_type);
}

#[test_only]
public struct BTC {}

#[test_only]
public struct SUI {}

#[test_only]
public struct USDC {}

#[test_only]
public struct MainMarket {}

#[test_only]
public struct DummyMarket {}

#[test]
fun test_ctoken_table_support_collateral_token_ok() {

    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);
    let mut table = new(scenario_value.ctx());

    table.support_collateral_token<MainMarket, BTC>();
    table.support_collateral_token<MainMarket, SUI>();

    assert!(table.is_supporting_collateral<MainMarket, BTC>());
    assert!(table.is_supporting_collateral<MainMarket, SUI>());

    assert!(table.ctoken_value_by_coin_type(type_name::with_defining_ids<BTC>()) == 0);
    assert!(table.ctoken_value_by_coin_type(type_name::with_defining_ids<SUI>()) == 0);

    let list_collaterals = table.supported_coin_types();
    assert!(list_collaterals.length() == 2);
    assert!(list_collaterals.contains(&type_name::with_defining_ids<BTC>()));
    assert!(list_collaterals.contains(&type_name::with_defining_ids<SUI>()));
    assert!(table.ctoken_value_by_ctoken_type(ctoken_type_name<MainMarket, SUI>()) == 0);
    assert!(table.ctoken_value_by_ctoken_type(ctoken_type_name<MainMarket, BTC>()) == 0);

    assert!(!table.is_supporting_collateral<DummyMarket, SUI>());

    table.remove_collateral<MainMarket, BTC>();
    table.remove_collateral<MainMarket, SUI>();

    destroy_empty(table);
    scenario_value.end();
}

#[test]
fun test_ctoken_table_join_split_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);
    let mut table = new(scenario_value.ctx());

    table.support_collateral_token<MainMarket, BTC>();

    let amount = 1000;
    let cbtc = sui::balance::create_for_testing<CToken<MainMarket, BTC>>(amount);

    table.join_ctoken<MainMarket, BTC>(cbtc);
    assert!(table.ctoken_value_by_coin_type(type_name::with_defining_ids<BTC>()) == amount);
    assert!(table.ctoken_value_by_ctoken_type(ctoken_type_name<MainMarket, BTC>()) == amount);

    let split_amount = 100;
    let split_cbtc = table.split_ctoken<MainMarket, BTC>(split_amount);
    assert!(split_cbtc.value() == split_amount);
    assert!(table.ctoken_value_by_coin_type(type_name::with_defining_ids<BTC>()) == amount - split_amount);
    assert!(table.ctoken_value_by_ctoken_type(ctoken_type_name<MainMarket, BTC>()) == amount - split_amount);

    sui::balance::destroy_for_testing(split_cbtc);

    let split_cbtc = table.split_ctoken<MainMarket, BTC>(amount - split_amount);
    assert!(split_cbtc.value() == amount - split_amount);
    assert!(table.ctoken_value_by_coin_type(type_name::with_defining_ids<BTC>()) == 0);
    assert!(table.ctoken_value_by_ctoken_type(ctoken_type_name<MainMarket, BTC>()) == 0);
    assert!(!table.is_supporting_collateral<MainMarket, BTC>());

    let list_collaterals = table.supported_coin_types();
    assert!(list_collaterals.is_empty());

    sui::balance::destroy_for_testing(split_cbtc);

    destroy_empty(table);


    scenario_value.end();
}

#[test]
#[expected_failure(abort_code = protocol::error::Err_Constraint_DoubleSupportCToken, location = Self)]
fun test_ctoken_table_support_collateral_token_fail() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);
    let mut table = new(scenario_value.ctx());

    table.support_collateral_token<MainMarket, BTC>();
    table.support_collateral_token<MainMarket, BTC>();

    table.remove_collateral<MainMarket, BTC>();

    destroy_empty(table);
    scenario_value.end();
}

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

